import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

// Min reduction over dim=1 of a [B, D1, D2] contiguous float tensor.
// Each thread computes one output element out[b, d] = min_i x[b, i, d].
// Consecutive threads map to consecutive d, so all global loads are
// perfectly coalesced even though the reduction stride is D2.
__global__ void min_reduce_dim1_kernel(const float* __restrict__ x,
                                       float* __restrict__ out,
                                       int dim1, int dim2,
                                       long long total) {
    long long stride = (long long)gridDim.x * blockDim.x;
    for (long long o = (long long)blockIdx.x * blockDim.x + threadIdx.x;
         o < total; o += stride) {
        int b = (int)(o / dim2);
        int d = (int)(o - (long long)b * dim2);
        const float* ptr = x + (long long)b * dim1 * dim2 + d;

        float m0, m1;
        if (dim1 > 1) {
            m0 = __ldg(ptr);
            m1 = __ldg(ptr + dim2);
        } else {
            m0 = __ldg(ptr);
            m1 = m0;
        }
        // Two independent accumulator chains to hide fmin latency.
        int i = 2;
        for (; i + 1 < dim1; i += 2) {
            float v0 = __ldg(ptr + (long long)i * dim2);
            float v1 = __ldg(ptr + (long long)(i + 1) * dim2);
            m0 = fminf(m0, v0);
            m1 = fminf(m1, v1);
        }
        if (i < dim1) {
            m0 = fminf(m0, __ldg(ptr + (long long)i * dim2));
        }
        out[o] = fminf(m0, m1);
    }
}

torch::Tensor min_reduce_dim1(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 3, "input must be 3D");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "input must be float32");

    auto xc = x.contiguous();
    int64_t batch = xc.size(0);
    int64_t dim1  = xc.size(1);
    int64_t dim2  = xc.size(2);

    auto out = torch::empty({batch, dim2}, xc.options());
    long long total = (long long)batch * dim2;
    if (total == 0) return out;

    int threads = 256;
    long long blocks = (total + threads - 1) / threads;
    if (blocks > 65535) blocks = 65535;

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    min_reduce_dim1_kernel<<<(int)blocks, threads, 0, stream>>>(
        xc.data_ptr<float>(), out.data_ptr<float>(),
        (int)dim1, (int)dim2, total);
    return out;
}
"""

_cpp_src = "torch::Tensor min_reduce_dim1(torch::Tensor x);"

_mod = load_inline(
    name="min_reduce_dim1_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["min_reduce_dim1"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Model that performs min reduction over a specific dimension,
    using a custom CUDA kernel for the dim == 1 case.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = dim

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        if (self.dim == 1 and x.is_cuda and x.dim() == 3
                and x.dtype == torch.float32):
            return _mod.min_reduce_dim1(x)
        return torch.min(x, dim=self.dim)[0]

